def _short(name: str) -> str:
    return name.rsplit(".", 1)[-1]


def _snake(value: str) -> str:
    output = []
    for index, character in enumerate(value):
        if character.isupper() and index and value[index - 1] != "_":
            output.append("_")
        output.append(character.lower())
    return "".join(output)


def _enum_values(name: str) -> dict[str, int]:
    return {_snake(item["name"]): item["value"] for item in _ENUMS[name]["variants"]}


def _enum_number(name: str, value: str) -> int:
    values = _enum_values(name)
    if value not in values:
        raise ValueError(f"unknown {_short(name)} value {value!r}")
    return values[value]


def _enum_name(name: str, value: int) -> str:
    for variant in _ENUMS[name]["variants"]:
        if variant["value"] == value:
            return _snake(variant["name"])
    raise ProtocolError(f"unknown {_short(name)} discriminator {value}")


class _Builder:
    _SIZES = {"i8": 1, "u8": 1, "bool": 1, "i16": 2, "u16": 2,
              "i32": 4, "u32": 4, "f32": 4, "i64": 8, "u64": 8,
              "f64": 8, "offset": 4, "struct1": 1, "struct2": 2,
              "struct4": 4, "struct8": 8}
    _FORMATS = {"i8": "<b", "u8": "<B", "bool": "<?", "i16": "<h",
                "u16": "<H", "i32": "<i", "u32": "<I", "f32": "<f",
                "i64": "<q", "u64": "<Q", "f64": "<d",
                "struct1": "<B", "struct2": "<H", "struct4": "<I",
                "struct8": "<Q"}

    def __init__(self, identifier: bytes):
        self.data = bytearray(b"\0\0\0\0" + identifier)

    def align(self, alignment: int = 4):
        while len(self.data) % alignment:
            self.data.append(0)

    def string(self, value: str) -> int:
        if not isinstance(value, str):
            raise TypeError("string field must be text")
        self.align()
        position = len(self.data)
        encoded = value.encode("utf-8")
        self.data.extend(struct.pack("<I", len(encoded)))
        self.data.extend(encoded)
        self.data.append(0)
        return position

    def byte_vector(self, value: bytes | bytearray | list[int]) -> int:
        raw = bytes(value)
        self.align()
        position = len(self.data)
        self.data.extend(struct.pack("<I", len(raw)))
        self.data.extend(raw)
        return position

    def offset_vector(self, values: list[Any]) -> int:
        self.align()
        position = len(self.data)
        self.data.extend(struct.pack("<I", len(values)))
        self.data.extend(b"\0" * (4 * len(values)))
        for index, value in enumerate(values):
            target = value() if callable(value) else value
            location = position + 4 + 4 * index
            self.data[location:location + 4] = struct.pack("<I", target - location)
        return position

    def scalar_vector(self, values: list[Any], kind: str) -> int:
        size = self._SIZES[kind]
        self.align(max(4, size))
        position = len(self.data)
        self.data.extend(struct.pack("<I", len(values)))
        for value in values:
            self.data.extend(struct.pack(self._FORMATS[kind], value))
        return position

    def table(self, fields: dict[int, tuple[str, Any]]) -> int:
        count = max(fields, default=-1) + 1
        entries = [0] * count
        size = 4
        table_alignment = 4
        for index, (kind, _) in fields.items():
            alignment = self._SIZES[kind]
            table_alignment = max(table_alignment, alignment)
            size = (size + alignment - 1) & -alignment
            entries[index] = size
            size += self._SIZES[kind]
        size = (size + table_alignment - 1) & -table_alignment
        self.align(4)
        vtable = len(self.data)
        self.data.extend(struct.pack("<HH", 4 + 2 * count, size))
        if count:
            self.data.extend(struct.pack("<" + "H" * count, *entries))
        self.align(table_alignment)
        table = len(self.data)
        self.data.extend(struct.pack("<i", table - vtable))
        self.data.extend(b"\0" * (size - 4))
        for index, (kind, value) in fields.items():
            location = table + entries[index]
            if kind == "offset":
                target = value() if callable(value) else value
                if target is not None:
                    self.data[location:location + 4] = struct.pack("<I", target - location)
            else:
                self.data[location:location + self._SIZES[kind]] = struct.pack(
                    self._FORMATS[kind], value
                )
        return table

    def finish(self, root: int) -> bytes:
        self.data[0:4] = struct.pack("<I", root)
        return bytes(self.data)


class _Reader:
    def __init__(self, data: bytes):
        self.data = data

    def _check(self, position: int, size: int):
        if position < 0 or size < 0 or position + size > len(self.data):
            raise ProtocolError("wire offset is out of bounds")

    def scalar(self, position: Optional[int], fmt: str, default=0):
        if position is None:
            return default
        self._check(position, struct.calcsize(fmt))
        return struct.unpack_from(fmt, self.data, position)[0]

    def field(self, table: Optional[int], index: int) -> Optional[int]:
        if table is None:
            return None
        self._check(table, 4)
        vtable = table - self.scalar(table, "<i")
        size = self.scalar(vtable, "<H")
        entry = vtable + 4 + 2 * index
        if entry + 2 > vtable + size:
            return None
        offset = self.scalar(entry, "<H")
        return None if offset == 0 else table + offset

    def offset(self, position: Optional[int]) -> Optional[int]:
        if position is None:
            return None
        value = self.scalar(position, "<I")
        return None if value == 0 else position + value

    def string(self, position: Optional[int]) -> Optional[str]:
        if position is None:
            return None
        length = self.scalar(position, "<I")
        self._check(position + 4, length)
        try:
            return self.data[position + 4:position + 4 + length].decode("utf-8")
        except UnicodeDecodeError as error:
            raise ProtocolError("wire string is not UTF-8") from error

    def vector_slots(self, position: Optional[int], size: int = 4) -> list[int]:
        if position is None:
            return []
        count = self.scalar(position, "<I")
        self._check(position + 4, count * size)
        return [position + 4 + index * size for index in range(count)]


_SCALAR = {
    "bool": ("bool", "<?"), "byte": ("i8", "<b"), "ubyte": ("u8", "<B"),
    "short": ("i16", "<h"), "ushort": ("u16", "<H"), "int": ("i32", "<i"),
    "uint": ("u32", "<I"), "long": ("i64", "<q"), "ulong": ("u64", "<Q"),
    "float": ("f32", "<f"), "double": ("f64", "<d"),
}


def _get(value: Any, name: str, default=None):
    if isinstance(value, dict):
        return value.get(name, default)
    return getattr(value, name, default)


def _object(name: str) -> dict[str, Any]:
    return _OBJECTS[name]


def _is_optional_wrapper(name: str) -> bool:
    value = _object(name)
    return value["kind"] == "struct" and len(value["fields"]) == 1


def _wrapper_union(value: dict[str, Any]):
    unions = [field for field in value["fields"] if field["type"]["kind"] == "union"]
    if value["kind"] != "table" or len(value["fields"]) != 2 or len(unions) != 1:
        return None
    return unions[0]


def _public_variant(public: str, union: str, variant: dict[str, Any]) -> str:
    path = union + "." + variant["name"]
    renamed = _SCHEMA["policy"]["union_variants"].get(path)
    if renamed:
        return _snake(renamed)
    name = _short(variant["payload"])
    short = _short(public)
    if name.startswith(short) and len(name) > len(short):
        name = name[len(short):]
    elif name.endswith(short) and len(name) > len(short):
        name = name[:-len(short)]
    for suffix in ("Expr", "Operation", "Target"):
        if short.endswith(suffix):
            base = short[:-len(suffix)]
            if name.startswith(base) and len(name) > len(base):
                name = name[len(base):]
            elif suffix == "Expr" and name.endswith(base) and len(name) > len(base):
                name = name[:-len(base)]
    return _snake(name)


def _union_variant(union: str, public: str, kind: str) -> dict[str, Any]:
    for variant in _ENUMS[union]["variants"]:
        if variant["payload"] is not None and _public_variant(public, union, variant) == kind:
            return variant
    raise ValueError(f"unknown {_short(public)} variant {kind!r}")


def _encode_scalar_value(base: str, value: Any, path: str):
    if base in ("float", "double") and not math.isfinite(value):
        raise ValueError(f"non-finite {path} is not portable")
    return value


def _encode_type(b: _Builder, ty: dict[str, Any], value: Any, path: str):
    kind = ty["kind"]
    if kind == "scalar":
        if ty["base"] == "string":
            return "offset", lambda: b.string(value)
        wire, _ = _SCALAR[ty["base"]]
        return wire, _encode_scalar_value(ty["base"], value, path)
    if kind == "enum":
        return _SCALAR[ty.get("base", "ubyte")][0], _enum_number(ty["name"], value)
    if kind == "object":
        name = ty["name"]
        if _is_optional_wrapper(name):
            inner = _object(name)["fields"][0]["type"]
            if inner["kind"] == "enum":
                number = _enum_number(inner["name"], value)
                base = inner.get("base", "ubyte")
            else:
                number = value
                base = inner["base"]
            return _SCALAR[base][0], number
        return "offset", lambda: _encode_table(b, name, value)
    raise ValueError(f"unsupported field type {kind} at {path}")


def _encode_vector(b: _Builder, ty: dict[str, Any], values: Any, path: str):
    element = ty["element"]
    if element["kind"] == "scalar" and element["base"] == "ubyte":
        return b.byte_vector(values)
    if element["kind"] == "scalar" and element["base"] != "string":
        return b.scalar_vector(list(values), _SCALAR[element["base"]][0])
    if element["kind"] == "enum":
        return b.scalar_vector([_enum_number(element["name"], item) for item in values],
                               _SCALAR[element.get("base", "ubyte")][0])
    if element["kind"] == "scalar":
        return b.offset_vector([lambda item=item: b.string(item) for item in values])
    return b.offset_vector([
        lambda item=item: _encode_table(b, element["name"], item) for item in values
    ])


def _encode_map(b: _Builder, ty: dict[str, Any], values: dict[str, Any], path: str):
    entry = _object(ty["entry"])
    key = next(field for field in entry["fields"] if field["key"])
    item = next(field for field in entry["fields"] if not field["key"])
    def encode_entry(name, value):
        fields = {key["id"]: ("offset", lambda: b.string(name))}
        field_kind, field_value = _encode_type(b, item["type"], value, path + "." + name)
        fields[item["id"]] = (field_kind, field_value)
        return b.table(fields)
    return b.offset_vector([
        lambda name=name, value=value: encode_entry(name, value)
        for name, value in sorted(values.items())
    ])


def _union_parts(b: _Builder, union: str, public: str, value: Any):
    kind = _get(value, "kind", "none")
    if kind in (None, "none"):
        return 0, None
    variant = _union_variant(union, public, kind)
    payload = _object(variant["payload"])
    unit = union + "." + variant["name"] in _SCHEMA["policy"]["unit_union_variants"]
    public_payload = variant["payload"] in _SCHEMA["public_objects"]
    if public_payload:
        payload_value = _get(value, "value")
    elif unit:
        field = payload["fields"][0]
        payload_value = {field["name"]: kind}
    elif _short(public) == "Value" and len(payload["fields"]) == 1:
        payload_value = {payload["fields"][0]["name"]: _get(value, "value")}
    else:
        payload_value = value
        if len(payload["fields"]) == 1:
            field = payload["fields"][0]
            if _get(value, field["name"]) is None and _get(value, "value") is not None:
                payload_value = {field["name"]: _get(value, "value")}
    return variant["value"], lambda: _encode_table(b, variant["payload"], payload_value)


def _encode_table(b: _Builder, name: str, value: Any) -> int:
    descriptor = _object(name)
    wrapper = _wrapper_union(descriptor)
    if wrapper is not None:
        tag, payload = _union_parts(b, wrapper["type"]["name"], name, value)
        return b.table({wrapper["id"] - 1: ("u8", tag), wrapper["id"]: ("offset", payload)})
    fields = {}
    union_ids = {field["id"] - 1 for field in descriptor["fields"]
                 if field["type"]["kind"] == "union"}
    for field in descriptor["fields"]:
        if field["id"] in union_ids:
            continue
        item = _get(value, field["name"])
        ty = field["type"]
        if ty["kind"] == "union":
            tag, payload = _union_parts(b, ty["name"], ty["name"], item)
            fields[field["id"] - 1] = ("u8", tag)
            if payload is not None:
                fields[field["id"]] = ("offset", payload)
        elif item is None:
            continue
        elif ty["kind"] == "vector":
            fields[field["id"]] = ("offset", lambda ty=ty, item=item: _encode_vector(b, ty, item, name + "." + field["name"]))
        elif ty["kind"] == "map":
            fields[field["id"]] = ("offset", lambda ty=ty, item=item: _encode_map(b, ty, item, name + "." + field["name"]))
        else:
            fields[field["id"]] = _encode_type(b, ty, item, name + "." + field["name"])
    return b.table(fields)


def _encode(operation: str, request: Any) -> bytes:
    descriptor = _OPERATIONS[operation]
    identifier = _ROOTS["request"]["identifier"].encode("ascii")
    b = _Builder(identifier)
    root = b.table({0: ("u32", 1), 1: ("u8", descriptor["request_tag"]),
                    2: ("offset", lambda: _encode_table(b, descriptor["request"], request))})
    return b.finish(root)


def _decode_type(r: _Reader, ty: dict[str, Any], position: Optional[int], path: str):
    kind = ty["kind"]
    if kind == "scalar":
        if ty["base"] == "string":
            return r.string(r.offset(position))
        _, fmt = _SCALAR[ty["base"]]
        return r.scalar(position, fmt)
    if kind == "enum":
        _, fmt = _SCALAR[ty.get("base", "ubyte")]
        return _enum_name(ty["name"], r.scalar(position, fmt))
    if kind == "object":
        name = ty["name"]
        if _is_optional_wrapper(name):
            if position is None:
                return None
            inner = _object(name)["fields"][0]["type"]
            if inner["kind"] == "enum":
                _, fmt = _SCALAR[inner.get("base", "ubyte")]
                return _enum_name(inner["name"], r.scalar(position, fmt))
            _, fmt = _SCALAR[inner["base"]]
            return r.scalar(position, fmt)
        return _decode_table(r, name, r.offset(position))
    raise ProtocolError(f"unsupported field type {kind} at {path}")


def _decode_vector(r: _Reader, ty: dict[str, Any], position: Optional[int], path: str):
    vector = r.offset(position)
    element = ty["element"]
    if element["kind"] == "scalar" and element["base"] == "ubyte":
        slots = r.vector_slots(vector, 1)
        return bytes(r.scalar(slot, "<B") for slot in slots)
    if element["kind"] == "scalar" and element["base"] != "string":
        wire, fmt = _SCALAR[element["base"]]
        return [r.scalar(slot, fmt) for slot in r.vector_slots(vector, _Builder._SIZES[wire])]
    if element["kind"] == "enum":
        wire, fmt = _SCALAR[element.get("base", "ubyte")]
        return [_enum_name(element["name"], r.scalar(slot, fmt))
                for slot in r.vector_slots(vector, _Builder._SIZES[wire])]
    if element["kind"] == "scalar":
        return [r.string(r.offset(slot)) for slot in r.vector_slots(vector)]
    return [_decode_table(r, element["name"], r.offset(slot)) for slot in r.vector_slots(vector)]


def _decode_map(r: _Reader, ty: dict[str, Any], position: Optional[int], path: str):
    entry = _object(ty["entry"])
    key = next(field for field in entry["fields"] if field["key"])
    item = next(field for field in entry["fields"] if not field["key"])
    result = {}
    for slot in r.vector_slots(r.offset(position)):
        table = r.offset(slot)
        name = _decode_type(r, key["type"], r.field(table, key["id"]), path + ".key")
        result[name] = _decode_type(r, item["type"], r.field(table, item["id"]), path + ".value")
    return result


def _decode_union(r: _Reader, union: str, public: str, tag: int,
                  position: Optional[int]):
    cls = _CLASSES[_short(public)]
    if tag == 0:
        return cls(kind="none")
    variant = next((item for item in _ENUMS[union]["variants"] if item["value"] == tag), None)
    if variant is None or variant["payload"] is None:
        raise ProtocolError(f"unknown {_short(union)} discriminator {tag}")
    payload = _object(variant["payload"])
    payload_position = r.offset(position)
    if payload_position is None:
        raise ProtocolError("union payload is missing")
    kind = _public_variant(public, union, variant)
    unit = union + "." + variant["name"] in _SCHEMA["policy"]["unit_union_variants"]
    public_payload = variant["payload"] in _SCHEMA["public_objects"]
    if unit or not payload["fields"]:
        return cls(kind=kind) if _short(public) != "Value" else cls(kind=kind, value=None)
    if public_payload:
        return cls(kind=kind, value=_decode_table(r, variant["payload"], payload_position))
    decoded = _decode_table_values(r, payload, payload_position)
    if _short(public) == "Value" and len(payload["fields"]) == 1:
        return cls(kind=kind, value=decoded[payload["fields"][0]["name"]])
    return cls(kind=kind, **decoded)


def _decode_table_values(r: _Reader, descriptor: dict[str, Any], position: int,
                         alias: Optional[dict[str, Any]] = None):
    values = {}
    union_ids = {field["id"] - 1 for field in descriptor["fields"]
                 if field["type"]["kind"] == "union"}
    for field in descriptor["fields"]:
        if field["id"] in union_ids:
            continue
        field_position = r.field(position, field["id"])
        ty = field["type"]
        if ty["kind"] == "union":
            tag = r.scalar(r.field(position, field["id"] - 1), "<B")
            values[field["name"]] = _decode_union(r, ty["name"], ty["name"], tag, field_position)
        elif ty["kind"] == "vector":
            values[field["name"]] = _decode_vector(r, ty, field_position, descriptor["name"] + "." + field["name"])
        elif ty["kind"] == "map":
            values[field["name"]] = _decode_map(r, ty, field_position, descriptor["name"] + "." + field["name"])
        else:
            value = _decode_type(r, ty, field_position, descriptor["name"] + "." + field["name"])
            required = field["protocol_required"] or (alias and field["name"] in alias["required_fields"])
            if value is None and required:
                raise ProtocolError(f"missing response field {descriptor['name']}.{field['name']}")
            values[field["name"]] = value
    return values


def _decode_table(r: _Reader, name: str, position: Optional[int], alias_name: Optional[str] = None):
    if position is None:
        return None
    descriptor = _object(name)
    wrapper = _wrapper_union(descriptor)
    if wrapper is not None:
        tag = r.scalar(r.field(position, wrapper["id"] - 1), "<B")
        return _decode_union(r, wrapper["type"]["name"], name, tag,
                             r.field(position, wrapper["id"]))
    alias = _SCHEMA["aliases"].get(alias_name or "")
    cls = _CLASSES[alias_name or _short(name)]
    values = _decode_table_values(r, descriptor, position, alias)
    for field in descriptor["fields"]:
        path = descriptor["name"] + "." + field["name"]
        response_alias = _SCHEMA["field_aliases"].get(path)
        if response_alias and values[field["name"]] is not None:
            target = field["type"]["name"]
            target_position = r.offset(r.field(position, field["id"]))
            values[field["name"]] = _decode_table(r, target, target_position, response_alias)
    return cls(**values)


def _read_response_unchecked(data: bytes, operation: str):
    root = _ROOTS["response"]
    identifier = root["identifier"].encode("ascii")
    if len(data) < 8 or data[4:8] != identifier:
        raise ProtocolError(f"missing {root['identifier']} file identifier")
    reader = _Reader(data)
    envelope = reader.scalar(0, "<I")
    if reader.scalar(reader.field(envelope, 0), "<I", 1) != 1:
        raise ProtocolError("unsupported response protocol version")
    tag = reader.scalar(reader.field(envelope, 1), "<B")
    payload = reader.field(envelope, 2)
    if tag == _SCHEMA["error_tag"]:
        portable = _decode_table(reader, _SCHEMA["error_payload"], reader.offset(payload))
        raise ClientError(portable.message, portable=portable)
    expected = _OPERATIONS[operation]
    if tag != expected["response_tag"]:
        raise ProtocolError(f"response variant does not match operation {operation}")
    return _decode_table(reader, expected["response"], reader.offset(payload))


def _read_response(data: bytes, operation: str):
    try:
        return _read_response_unchecked(data, operation)
    except (ClientError, ProtocolError):
        raise
    except Exception as error:
        raise ProtocolError(f"malformed response: {error}") from error


def _read_index(reader: _Reader, position: Optional[int]):
    return _decode_table(reader, _SCHEMA["standalone_type"], position)


def encode_index_definition(value: IndexDefinition) -> bytes:
    b = _Builder(b"\0\0\0\0")
    return b.finish(_encode_table(b, "SearchKernel.V1.IndexDefinition", value))


class Client:
    def __init__(self, transport):
        self._transport = transport

    def _call(self, operation: str, request: Any):
        try:
            response = self._transport.call(_encode(operation, request))
        except ClientError:
            raise
        except Exception as error:
            raise ClientError(str(error), transport=error) from error
        try:
            return _read_response(response, operation)
        except ClientError:
            raise
        except Exception as error:
            raise ClientError(f"malformed native response: {error}") from error

    def analyze(self, request):
        return self._call("analyze", request)

    def delete(self, request):
        return self._call("delete", request)

    def describe(self, request):
        return self._call("describe", request)

    def get(self, request):
        return self._call("get", request)

    def insert(self, request):
        return self._call("insert", request)

    def inspect_query(self, request):
        return self._call("inspect_query", request)

    def patch(self, request):
        return self._call("patch", request)

    def search(self, request):
        return self._call("search", request)

    def upsert(self, request):
        return self._call("upsert", request)



